#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

_gh_ready() { command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; }

run_wizard() {
  if [[ "${1:-}" == "--help" || "${1:-}" == "-h" ]]; then
    cat <<'EOF'
Usage: bash scripts/wizards/upgrade-consumer-wizard.sh [options]

Interactive 5-stage wizard to upgrade an existing EPURE consumer repository
from v1/v2 to v3 (https://giskard-ai.github.io/epure/installation):
  Stage 1: Target repository, checkout path, pinned SHA & dry-run migration checklist
  Stage 2: Verify GitHub App permissions & environment-scoped secrets (<llm-env>, release)
  Stage 3: Apply managed workflows (.github/workflows/*, .github/zizmor.yml) & merge .github/agents.yml
  Stage 4: Review diff, commit & push upgrade to dev
  Stage 5: Apply 5 Repository Rulesets & squash-only merge governance

Options:
  --help, -h   Show this help message and exit
EOF
    return 0
  fi

  local script_dir epure_root setup_cli default_sha
  script_dir="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
  epure_root="$(cd "$script_dir/../.." && pwd)"
  setup_cli="$epure_root/dist/cli/setup-repo.mjs"
  default_sha="$(git -C "$epure_root" rev-parse HEAD 2>/dev/null || echo "")"

  TOTAL_STAGES=5

  banner "EPURE v3 Consumer Repository Upgrade Wizard"

  # ── Stage 1: Inspect consumer repository & preview v3 migration ──────────
  stage "Inspect consumer repository & preview v3 migration"
  say "We'll inspect your existing consumer repository and run a non-destructive --dry-run migration check."
  ask CONSUMER_REPO "Target GitHub repository slug (owner/repo):"
  ask CONSUMER_DIR "Local path to the consumer repository checkout:"
  if [[ -n "$default_sha" ]]; then
    note "Detected local EPURE commit SHA: $default_sha"
  fi
  ask EPURE_PINNED_SHA "40-character EPURE commit SHA to pin (v3.0.0):"
  ask AGENT_APP_ID "Numeric GitHub App ID for <owner>-epure-agent:"
  ask RELEASE_APP_ID "Numeric GitHub App ID for <owner>-epure-release:"
  ask LLM_ENV "GitHub Environment name for the agent job (e.g. epure-agent):"
  write_env CONSUMER_REPO "$CONSUMER_REPO"
  write_env CONSUMER_DIR "$CONSUMER_DIR"
  write_env EPURE_PINNED_SHA "$EPURE_PINNED_SHA"
  write_env AGENT_APP_ID "$AGENT_APP_ID"
  write_env RELEASE_APP_ID "$RELEASE_APP_ID"
  write_env LLM_ENV "$LLM_ENV"

  step "Running setup-repo --dry-run to compute your v3 Migration Checklist..."
  local dry_run_extra_flags=()
  if _gh_ready && [[ -n "${AGENT_APP_ID:-}" && -n "${RELEASE_APP_ID:-}" ]]; then
    dry_run_extra_flags+=(--apply-github-settings)
  fi
  node "$setup_cli" \
    --repo "$CONSUMER_REPO" \
    --target-dir "$CONSUMER_DIR" \
    --pinned-sha "$EPURE_PINNED_SHA" \
    --agent-app-id "$AGENT_APP_ID" \
    --release-app-id "$RELEASE_APP_ID" \
    --llm-env "$LLM_ENV" \
    --dry-run \
    "${dry_run_extra_flags[@]}"
  pause "Review the Migration Checklist above, then press Enter to continue"

  # ── Stage 2: Verify GitHub App permissions & environment secrets ─────────
  stage "Verify GitHub App permissions & environment secrets"
  say "Ensure both GitHub Apps and environment-scoped secrets match the EPURE v3 contract."
  open_url "https://github.com/${CONSUMER_REPO}/settings/environments"
  step "Confirm environment '$LLM_ENV' holds EPURE_AGENT_APP_ID, EPURE_AGENT_APP_PRIVATE_KEY, and LLM_API_KEY (plus CURSOR_API_KEY if harness: cursor)."
  step "Confirm environment 'release' holds EPURE_RELEASE_APP_ID and EPURE_RELEASE_APP_PRIVATE_KEY with Required Reviewers enabled."
  step "Confirm Agent App permissions include contents:write, issues:write, pull_requests:write, checks:write."
  if confirm "Do you need to rotate or set LLM_API_KEY in environment '$LLM_ENV' now?"; then
    ask_secret LLM_API_KEY "Paste the new LLM_API_KEY:"
    write_env LLM_API_KEY "$LLM_API_KEY"
    if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
      printf '%s' "$LLM_API_KEY" | gh secret set LLM_API_KEY -R "$CONSUMER_REPO" --env "$LLM_ENV"
      WRITTEN_SECRET+=("LLM_API_KEY ($LLM_ENV)")
    else
      SKIPPED+=("gh secret set LLM_API_KEY -R $CONSUMER_REPO --env $LLM_ENV")
    fi
  fi
  pause "Press Enter once GitHub App permissions and environment secrets are verified"

  # ── Stage 3: Apply managed workflows & merge .github/agents.yml ──────────
  stage "Apply managed workflows & merge .github/agents.yml"
  say "Managed files (epure-issue-command.yml, epure-check.yml, pr-title.yml, release.yml, .github/zizmor.yml) will be updated."
  note "Bootstrapped files (ci.yml, renovate.json, <reviewers_dir>/*.md) and your custom settings in .github/agents.yml are preserved."
  if confirm "Apply managed file updates and .github/agents.yml v3 merge in '$CONSUMER_DIR'?"; then
    node "$setup_cli" \
      --repo "$CONSUMER_REPO" \
      --target-dir "$CONSUMER_DIR" \
      --pinned-sha "$EPURE_PINNED_SHA" \
      --llm-env "$LLM_ENV" \
      --apply
  else
    SKIPPED+=("Apply managed files in $CONSUMER_DIR")
  fi
  pause "Press Enter to continue to git review and commit"

  # ── Stage 4: Review diff, commit & push upgrade to dev ───────────────────
  stage "Review diff, commit & push upgrade to dev"
  say "Inspect the updated files in '$CONSUMER_DIR' and push them to 'dev' before updating Repository Rulesets."
  step "In '$CONSUMER_DIR', review 'git diff', commit the .github/ changes, and push to 'dev'."
  git -C "$CONSUMER_DIR" status -s || true
  pause "Press Enter once the upgrade commit is pushed to 'dev'"

  # ── Stage 5: Apply 5 Repository Rulesets & squash-only governance ────────
  stage "Apply 5 Repository Rulesets & squash-only governance"
  say "Finally, we'll synchronize squash-only merge settings and the 5 Repository Rulesets on GitHub."
  if confirm "Apply squash-only merge settings and the 5 Repository Rulesets to '$CONSUMER_REPO'?"; then
    node "$setup_cli" \
      --repo "$CONSUMER_REPO" \
      --target-dir "$CONSUMER_DIR" \
      --pinned-sha "$EPURE_PINNED_SHA" \
      --agent-app-id "$AGENT_APP_ID" \
      --release-app-id "$RELEASE_APP_ID" \
      --llm-env "$LLM_ENV" \
      --apply \
      --apply-github-settings
  else
    SKIPPED+=("Apply GitHub rulesets on $CONSUMER_REPO (--apply-github-settings)")
  fi

  finish
}

run_wizard "$@"; exit
